    const stateText = { idle: '\u672A\u64AD\u653E', preparing: '\u6E96\u5099\u4E2D', playing: '\u64AD\u653E\u4E2D', paused: '\u5DF2\u66AB\u505C' }[snapshot.state] || '\u2014';
