    $('dur').textContent = snapshot.durationMs > 0 ? clock(snapshot.durationMs) : '--:--';
    $('pause').disabled = snapshot.state !== 'playing';
    $('resume').disabled = snapshot.state !== 'paused';
    $('next').disabled = snapshot.state === 'idle';
